import sys

def main():
    lines = sys.stdin.read().strip().split('\n')
    if not lines:
        return
    n = int(lines[0])
    ops = lines[1:n+1]

    typedefs = {}

    def resolve_type(type_str):
        s = type_str.strip()
        stars = 0
        amps = 0
        base_name = ""

        i = 0
        while i < len(s):
            if s[i] == '*':
                stars += 1
                i += 1
            elif s[i] == '&':
                amps += 1
                i += 1
            else:
                break

        base_name = s[i:]

        if base_name not in typedefs:
            if base_name == 'void':
                current_stars = 0
                current_amps = 0
            elif base_name == 'errtype':
                return 'errtype'
            else:
                return 'errtype'
        else:
            resolved = typedefs[base_name]
            if resolved == 'errtype':
                return 'errtype'
            parts = resolved.split('*')
            current_stars = len(parts) - 1
            current_amps = 0

        total_amps = amps + current_amps
        total_stars = stars + current_stars

        net = total_stars - total_amps

        if net >= 0:
            return 'void' + '*' * net
        else:
            return 'errtype'

    for op in ops:
        parts = op.split()
        cmd = parts[0]

        if cmd == 'typedef':
            A = parts[1]
            B = parts[2]
            resolved = resolve_type(A)
            typedefs[B] = resolved
        elif cmd == 'typeof':
            A = parts[1]
            result = resolve_type(A)
            print(result)

if __name__ == "__main__":
    main()
